// Constructor
CChanRTS::CChanRTS(springai::OOAICallback* callback):
    callback(callback),
    skirmishAIId(callback != NULL ? callback->GetSkirmishAIId() : -1),
    shouldStop(false),
    inferenceReady(false),
    collectTrainingData(true),
    finalGameReward(0.0f),
    lastInferenceFrame(0),
    inferenceCount(0),
    totalInferenceTime(0.0),
    useMLInference(false),
    replayMode(false),
    gameId(0),
    playerSkill(20.0f)
{
    // Initialize the inference thread
    StartInferenceThread();
    
    // Initialize game state
    currentState.currentFrame = 0;
    currentActions.frame = 0;
    
    // Initialize ML model and spatial input manager
    LoadMLModel();
    InitializeSpatialInputManager();
    
    // Check for training data collection configuration
    CheckDataCollectionConfig();
    
    // Send initialization message and debug info
    if (callback) {
        const std::unique_ptr<springai::Game> game(callback->GetGame());
        if (game) {
            game->SendTextMessage("/say ChanRTS ML AI initialized with threaded inference!", 0);
            
            // Debug environment variables
            game->SendTextMessage("/say === ENVIRONMENT DEBUG ===", 0);
            
            const char* collectEnv = std::getenv("CHANRTS_COLLECT_DATA");
            const char* outputDirEnv = std::getenv("CHANRTS_OUTPUT_DIR");
            const char* replayModeEnv = std::getenv("CHANRTS_REPLAY_MODE");
            const char* configPathEnv = std::getenv("CHANRTS_CONFIG_PATH");
            const char* playerSkillEnv = std::getenv("CHANRTS_PLAYER_SKILL");
            const char* gameIdEnv = std::getenv("CHANRTS_GAME_ID");
            
            std::string envMsg = "/say CHANRTS_COLLECT_DATA=" + std::string(collectEnv ? collectEnv : "NULL");
            game->SendTextMessage(envMsg.c_str(), 0);
            
            envMsg = "/say CHANRTS_OUTPUT_DIR=" + std::string(outputDirEnv ? outputDirEnv : "NULL");
            game->SendTextMessage(envMsg.c_str(), 0);
            
            envMsg = "/say CHANRTS_REPLAY_MODE=" + std::string(replayModeEnv ? replayModeEnv : "NULL");
            game->SendTextMessage(envMsg.c_str(), 0);
            
            envMsg = "/say CHANRTS_CONFIG_PATH=" + std::string(configPathEnv ? configPathEnv : "NULL");
            game->SendTextMessage(envMsg.c_str(), 0);
            
            envMsg = "/say CHANRTS_PLAYER_SKILL=" + std::string(playerSkillEnv ? playerSkillEnv : "NULL");
            game->SendTextMessage(envMsg.c_str(), 0);
            
            envMsg = "/say CHANRTS_GAME_ID=" + std::string(gameIdEnv ? gameIdEnv : "NULL");
            game->SendTextMessage(envMsg.c_str(), 0);
            
            // Debug final configuration state
            game->SendTextMessage("/say === CONFIG STATE ===", 0);
            std::string debugMsg = "/say collectTrainingData: " + std::string(collectTrainingData ? "TRUE" : "FALSE");
            game->SendTextMessage(debugMsg.c_str(), 0);
            
            std::string outputMsg = "/say dataOutputDir: " + (dataOutputDir.empty() ? "EMPTY" : dataOutputDir);
            game->SendTextMessage(outputMsg.c_str(), 0);
            
            std::string replayMsg = "/say replayMode: " + std::string(replayMode ? "TRUE" : "FALSE");
            game->SendTextMessage(replayMsg.c_str(), 0);
            
            std::string skillMsg = "/say playerSkill: " + std::to_string(playerSkill);
            game->SendTextMessage(skillMsg.c_str(), 0);
            
            std::string gameIdMsg = "/say gameId: " + std::to_string(gameId);
            game->SendTextMessage(gameIdMsg.c_str(), 0);
            
            game->SendTextMessage("/say === END DEBUG ===", 0);
        }
    }
}

// Destructor
CChanRTS::~CChanRTS() {
    StopInferenceThread();
    
    // Save training data before destruction
    if (collectTrainingData && !trainingBuffer.empty()) {
        CalculateFinalRewards();
        
        // Use binary format for replay processing, CSV for regular gameplay
        if (replayMode) {
            SaveTrainingDataBinary();
        } else {
            SaveTrainingData();
        }
    }
}

// Main event handler
int CChanRTS::HandleEvent(int topic, const void* data) {
    try {
        switch (topic) {
            case EVENT_INIT: {
                // AI initialization
                break;
            }
            
            case EVENT_UPDATE: {
                const struct SUpdateEvent* evt = (const struct SUpdateEvent*) data;
                HandleUpdate(evt->frame);
                break;
            }
            
            case EVENT_UNIT_CREATED: {
                const struct SUnitCreatedEvent* evt = (const struct SUnitCreatedEvent*) data;
                HandleUnitCreated(evt->unit, evt->builder);
                break;
            }
            
            case EVENT_UNIT_DESTROYED: {
                const struct SUnitDestroyedEvent* evt = (const struct SUnitDestroyedEvent*) data;
                HandleUnitDestroyed(evt->unit);
                break;
            }
            
            case EVENT_UNIT_IDLE: {
                const struct SUnitIdleEvent* evt = (const struct SUnitIdleEvent*) data;
                HandleUnitIdle(evt->unit);
                break;
            }
            
            case EVENT_RELEASE: {
                HandleGameEnd();
                break;
            }
            
            default: {
                // Handle other events as needed
                break;
            }
        }
    } catch (const std::exception& e) {
        // Log error but don't crash the AI
        if (callback) {
            const std::unique_ptr<springai::Game> game(callback->GetGame());
            if (game) {
                std::string errorMsg = std::string("/say ChanRTS Error: ") + e.what();
                game->SendTextMessage(errorMsg.c_str(), 0);
            }
        }
        return 1; // Signal error but continue
    }
    
    return 0; // Success
}

// Handle game updates (30 FPS)
void CChanRTS::HandleUpdate(int frame) {
    std::lock_guard<std::mutex> lock(stateMutex);
    
    // Update current frame
    currentState.currentFrame = frame;
    
    // Extract comprehensive game state
    ExtractGameState(currentState);
    
    // Signal inference thread if it's ready
    if (inferenceReady.load() && (frame - lastInferenceFrame) > 1) {
        // Copy state for inference thread
        nextState = currentState;
        lastInferenceFrame = frame;
        inferenceCondition.notify_one();
    }
    
    // Execute current actions from previous inference
    if (currentActions.frame > 0 && (frame - currentActions.frame) < 60) { // Execute for up to 2 seconds
        ExecuteActions(currentActions);
    }
    
    // Collect training data at different intervals depending on mode
    int collectionInterval = replayMode ? 30 : 900; // Every 1 second in replay mode, every 30 seconds normally
    if (collectTrainingData && frame % collectionInterval == 0) {
        CollectTrainingData(currentState, currentActions);
        
        // Send debug message about data collection (less frequent in replay mode to avoid spam)
        if (callback && (!replayMode || frame % 900 == 0)) {
            const std::unique_ptr<springai::Game> game(callback->GetGame());
            if (game) {
                std::string msg = "/say DATA COLLECTION: frame " + std::to_string(frame) + 
                                " interval=" + std::to_string(collectionInterval) +
                                " buffer=" + std::to_string(trainingBuffer.size()) + 
                                " replayMode=" + std::string(replayMode ? "TRUE" : "FALSE");
                game->SendTextMessage(msg.c_str(), 0);
            }
        }
    }
    
    // Debug message for first few frames to show collection state
    if (frame <= 90 && frame % 30 == 0) {
        if (callback) {
            const std::unique_ptr<springai::Game> game(callback->GetGame());
            if (game) {
                std::string debugMsg = "/say Frame " + std::to_string(frame) + 
                                     " collectTrainingData=" + std::string(collectTrainingData ? "TRUE" : "FALSE") +
                                     " interval=" + std::to_string(collectionInterval);
                game->SendTextMessage(debugMsg.c_str(), 0);
            }
        }
    }
}

// Handle unit creation
void CChanRTS::HandleUnitCreated(int unitId, int builderId) {
    // Track new units
    unitCommandFrames[unitId] = currentState.currentFrame;
    unitToLastCommand[unitId] = 0; // No command yet
}

// Handle unit destruction
void CChanRTS::HandleUnitDestroyed(int unitId) {
    // Clean up tracking data
    unitCommandFrames.erase(unitId);
    unitToLastCommand.erase(unitId);
}

// Handle idle units
void CChanRTS::HandleUnitIdle(int unitId) {
    // Mark unit as available for new commands
    unitToLastCommand[unitId] = 0;
}

// Handle game end
void CChanRTS::HandleGameEnd() {
    if (collectTrainingData && !trainingBuffer.empty()) {
        CalculateFinalRewards();
        SaveTrainingData();
    }
}

// Start the inference thread
void CChanRTS::StartInferenceThread() {
    shouldStop = false;
    inferenceReady = true;
    inferenceThread = std::make_unique<std::thread>(&CChanRTS::InferenceThreadLoop, this);
}

// Stop the inference thread
void CChanRTS::StopInferenceThread() {
    shouldStop = true;
    inferenceCondition.notify_all();
    
    if (inferenceThread && inferenceThread->joinable()) {
        inferenceThread->join();
    }
}

// Main inference thread loop
void CChanRTS::InferenceThreadLoop() {
    GameState localState;
    MLAction localAction;
    
    while (!shouldStop.load()) {
        // Wait for new state data
        std::unique_lock<std::mutex> lock(stateMutex);
        inferenceCondition.wait(lock, [this, &localState] { 
            return shouldStop.load() || nextState.currentFrame > localState.currentFrame; 
        });
        
        if (shouldStop.load()) break;
        
        // Copy state for processing
        localState = nextState;
        lock.unlock();
        
        // Run ML inference
        auto startTime = std::chrono::high_resolution_clock::now();
        
        RunMLInference(localState, localAction);
        
        auto endTime = std::chrono::high_resolution_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::microseconds>(endTime - startTime);
        
        // Update performance metrics
        inferenceCount++;
        totalInferenceTime += duration.count() / 1000.0; // Convert to milliseconds
        
        // Update current actions with thread safety
        {
            std::lock_guard<std::mutex> actionLock(actionMutex);
            pendingActions = localAction;
            pendingActions.frame = localState.currentFrame;
            
            // Swap pending actions to current if they're newer
            if (pendingActions.frame > currentActions.frame) {
                currentActions = pendingActions;
            }
        }
    }
}

// ML inference placeholder - replace with actual model
void CChanRTS::RunMLInference(const GameState& state, MLAction& action) {
    action.unitActions.clear();
    action.strategicState = 1; // Default to economic phase
    action.frame = state.currentFrame;
    
    // Early exit if ML inference is not available or enabled
    if (!useMLInference || !mlModel || !spatialInputManager) {
        // Fallback to simple rule-based behavior
        printf("ChanRTS: Using rule-based fallback (ML not available)\n");
        
        // Simple rule: idle units should move randomly or build
        for (const auto& unitInfo : state.allUnits) {
            if (!unitInfo.isEnemy && unitInfo.isIdle) {
                UnitAction unitAction;
                unitAction.unitId = unitInfo.id;
                
                // Simple strategy: builders build, others move randomly
                if (IsUnitEconomic(unitInfo.defId)) {
                    unitAction.type = UnitAction::BUILD;
                    // Find a build location (simplified)
                    unitAction.x = unitInfo.x + (rand() % 200 - 100);
                    unitAction.y = unitInfo.y + (rand() % 200 - 100);
                    unitAction.z = unitInfo.z;
                    unitAction.buildUnitDefId = 1; // Placeholder
                } else {
                    unitAction.type = UnitAction::MOVE;
                    unitAction.x = rand() % state.mapWidth;
                    unitAction.y = rand() % state.mapHeight;
                    unitAction.z = 0;
                }
                
                unitAction.priority = 50;
                action.unitActions.push_back(unitAction);
            }
        }
        return;
    }
    
    try {
        printf("ChanRTS: Running ML inference for frame %d\n", state.currentFrame);
        
        // Convert game state to spatial tensor
        SpatialTensor inputTensor = GameStateToSpatialTensor(state);
        printf("ChanRTS: Generated spatial tensor %dx%dx%d\n", inputTensor.width, inputTensor.height, inputTensor.channels);
        
        // Run inference through the neural network
        MLOutput mlOutput = mlModel->Inference(inputTensor);
        printf("ChanRTS: ML inference completed\n");
        
        // Convert ML output to game actions
        action = MLOutputToMLAction(mlOutput, state.currentFrame);
        printf("ChanRTS: Generated %d unit actions from ML output\n", (int)action.unitActions.size());
        
    } catch (const std::exception& e) {
        printf("ChanRTS: ML inference failed with error: %s\n", e.what());
        printf("ChanRTS: Falling back to rule-based behavior\n");
        
        // Fallback to rule-based behavior on ML failure
        for (const auto& unitInfo : state.allUnits) {
            if (!unitInfo.isEnemy && unitInfo.isIdle) {
                UnitAction unitAction;
                unitAction.unitId = unitInfo.id;
                unitAction.type = UnitAction::MOVE;
                unitAction.x = rand() % state.mapWidth;
                unitAction.y = rand() % state.mapHeight;
                unitAction.z = 0;
                unitAction.priority = 50;
                action.unitActions.push_back(unitAction);
            }
        }
    }
}

// Execute ML actions
void CChanRTS::ExecuteActions(const MLAction& actions) {
    for (const auto& unitAction : actions.unitActions) {
        if (IsActionValid(unitAction)) {
            ExecuteUnitAction(unitAction);
        }
    }
}

// Execute individual unit action
void CChanRTS::ExecuteUnitAction(const UnitAction& action) {
    if (!callback) return;
    
    // Get unit pointer
    std::vector<springai::Unit*> friendlyUnits = callback->GetFriendlyUnits();
    springai::Unit* targetUnit = nullptr;
    
    for (springai::Unit* unit : friendlyUnits) {
        if (unit->GetUnitId() == action.unitId) {
            targetUnit = unit;
            break;
        }
    }
    
    if (!targetUnit) {
        // Clean up memory
        for (springai::Unit* unit : friendlyUnits) {
            delete unit;
        }
        return;
    }
    
    // Execute action based on type
    try {
        switch (action.type) {
            case UnitAction::MOVE: {
                springai::AIFloat3 pos;
                pos.x = action.x;
                pos.y = action.y;
                pos.z = action.z;
                targetUnit->MoveTo(pos);
                break;
            }
            
            case UnitAction::ATTACK: {
                // Find target unit (simplified)
                std::vector<springai::Unit*> enemyUnits = callback->GetEnemyUnits();
                for (springai::Unit* enemy : enemyUnits) {
                    if (enemy->GetUnitId() == action.targetUnitId) {
                        targetUnit->Attack(enemy);
                        break;
                    }
                }
                for (springai::Unit* enemy : enemyUnits) {
                    delete enemy;
                }
                break;
            }
            
            case UnitAction::BUILD: {
                // Simplified build command
                springai::AIFloat3 pos;
                pos.x = action.x;
                pos.y = action.y;
                pos.z = action.z;
                
                // Get unit def (simplified - would need proper unit def lookup)
                std::vector<springai::UnitDef*> unitDefs = callback->GetUnitDefs();
                if (!unitDefs.empty() && action.buildUnitDefId < unitDefs.size()) {
                    targetUnit->Build(unitDefs[action.buildUnitDefId], pos, 0);
                }
                for (springai::UnitDef* unitDef : unitDefs) {
                    delete unitDef;
                }
                break;
            }
            
            case UnitAction::STOP: {
                targetUnit->Stop();
                break;
            }
            
            default: {
                // Do nothing for unknown actions
                break;
            }
        }
        
        // Update command tracking
        unitToLastCommand[action.unitId] = currentState.currentFrame;
        
    } catch (const std::exception& e) {
        // Log error but continue
        if (callback) {
            const std::unique_ptr<springai::Game> game(callback->GetGame());
            if (game) {
                std::string errorMsg = std::string("/say Action error: ") + e.what();
                game->SendTextMessage(errorMsg.c_str(), 0);
            }
        }
    }
    
    // Clean up memory
    for (springai::Unit* unit : friendlyUnits) {
        delete unit;
    }
}

// Validate action before execution
bool CChanRTS::IsActionValid(const UnitAction& action) {
    // Basic validation
    if (action.unitId < 0 || action.type == UnitAction::NONE) {
        return false;
    }
    
    // Check if unit was commanded recently (avoid spam)
    auto it = unitToLastCommand.find(action.unitId);
    if (it != unitToLastCommand.end()) {
        int framesSinceLastCommand = currentState.currentFrame - it->second;
        if (framesSinceLastCommand < 5) { // Wait at least 5 frames between commands
            return false;
        }
    }
    
    // Check coordinate bounds (raw map coordinates)
    if (action.type == UnitAction::MOVE || action.type == UnitAction::BUILD) {
        if (action.x < 0 || action.x > currentState.mapWidth || action.z < 0 || action.z > currentState.mapHeight) {
            return false;
        }
    }
    
    return true;
}

// Utility functions
float CChanRTS::NormalizeCoordinate(float coord, float mapSize) {
    return std::max(0.0f, std::min(1.0f, coord / mapSize));
}

float CChanRTS::CalculateGameProgress() {
    // Simple progress estimation based on frame count
    // Typical RTS games last 1800-3600 frames (1-2 minutes at 30 FPS)
    float estimatedGameLength = 3600.0f;
    return std::min(1.0f, currentState.currentFrame / estimatedGameLength);
}

