// Main feature extraction method
void CChanRTS::ExtractGameState(GameState& state) {
    if (!callback) return;
    
    ExtractMapFeatures(state);
    ExtractUnitFeatures(state);
    ExtractEconomicFeatures(state);
    ExtractStrategicFeatures(state);
    
    state.gameProgress = CalculateGameProgress();
}

// Extract map and terrain features
void CChanRTS::ExtractMapFeatures(GameState& state) {
    try {
        const std::unique_ptr<springai::Map> map(callback->GetMap());
        if (!map) return;
        
        state.mapWidth = map->GetWidth();
        state.mapHeight = map->GetHeight();
        
        // Get terrain data
        state.heightMap = map->GetHeightMap();
        state.slopeMap = map->GetSlopeMap();
        
        // Get visibility maps
        state.losMap = map->GetLosMap();
        state.radarMap = map->GetRadarMap();
        
        // Get metal map (resource locations) - not available in this Spring version
        // TODO: Find alternative way to get resource locations
        state.metalMap.clear();
        
    } catch (const std::exception& e) {
        // Log error but continue
        if (callback) {
            const std::unique_ptr<springai::Game> game(callback->GetGame());
            if (game) {
                std::string errorMsg = std::string("/say Map extraction error: ") + e.what();
                game->SendTextMessage(errorMsg.c_str(), 0);
            }
        }
    }
}

// Extract comprehensive unit features
void CChanRTS::ExtractUnitFeatures(GameState& state) {
    try {
        state.allUnits.clear();
        state.friendlyUnitIds.clear();
        state.enemyUnitIds.clear();
        
        // Get friendly units
        std::vector<springai::Unit*> friendlyUnits = callback->GetFriendlyUnits();
        for (springai::Unit* unit : friendlyUnits) {
            GameState::UnitInfo unitInfo = ExtractComprehensiveUnitInfo(unit, false, state.currentFrame);
            state.allUnits.push_back(unitInfo);
            state.friendlyUnitIds.push_back(unitInfo.id);
        }
        
        // Clean up friendly units
        for (springai::Unit* unit : friendlyUnits) {
            delete unit;
        }
        
        // Get enemy units
        std::vector<springai::Unit*> enemyUnits = callback->GetEnemyUnits();
        for (springai::Unit* unit : enemyUnits) {
            GameState::UnitInfo unitInfo = ExtractComprehensiveUnitInfo(unit, true, state.currentFrame);
            state.allUnits.push_back(unitInfo);
            state.enemyUnitIds.push_back(unitInfo.id);
        }
        
        // Clean up enemy units
        for (springai::Unit* unit : enemyUnits) {
            delete unit;
        }
        
    } catch (const std::exception& e) {
        // Log error but continue
        if (callback) {
            const std::unique_ptr<springai::Game> game(callback->GetGame());
            if (game) {
                std::string errorMsg = std::string("/say Unit extraction error: ") + e.what();
                game->SendTextMessage(errorMsg.c_str(), 0);
            }
        }
    }
}

